async function test() {
  const rpc = "https://arb1.arbitrum.io/rpc";
  async function call(to, data) {
    const res = await fetch(rpc, {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({jsonrpc: "2.0", id: 1, method: "eth_call", params: [{to, data}, "latest"]})
    });
    return (await res.json()).result;
  }
  // symbol() selector is 0x95d89b41
  console.log("WETH symbol:", await call("0x82aF49447D8a07e3bd95BD0d56f35241523fBab1", "0x95d89b41"));
  console.log("Native USDC symbol:", await call("0xaf88d065e77c8cC2239327C5EDb3A432268e5831", "0x95d89b41"));
  console.log("Bridged USDC symbol:", await call("0xFF970A61A04b1cA14834A43f5dE4533eBDDB5CC8", "0x95d89b41"));
}
test();
'

