async function test() {
  const rpc = "https://arb1.arbitrum.io/rpc";
  async function call(to, data) {
    const res = await fetch(rpc, {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({jsonrpc: "2.0", id: 1, method: "eth_call", params: [{to, data}, "latest"]})
    });
    return (await res.json()).result;
  }
  const hexToString = hex => Buffer.from(hex.slice(130, 130 + parseInt(hex.slice(66, 130), 16) * 2), "hex").toString();
  console.log("Bridged USDC name:", hexToString(await call("0xFF970A61A04b1cA14834A43f5dE4533eBDDB5CC8", "0x06fdde03")));
  console.log("Native USDC name:", hexToString(await call("0xaf88d065e77c8cC2239327C5EDb3A432268e5831", "0x06fdde03")));
}
test();
'

